#include <cuda.h>
#include <cuda_runtime.h>

// Kernel 1: compute per-channel mean and variance of (x * scale)
// Grid: (C,), Block: (BLOCK,)
// Each block handles one channel, iterates over N rows
template <int BLOCK>
__global__ void scale_bn_stats_kernel(
    const float* __restrict__ x,      // [N, C]
    const float* __restrict__ scale,  // [C]
    float* __restrict__ mean_buf,     // [C]
    float* __restrict__ var_buf,      // [C]
    int N, int C
) {
    int c = blockIdx.x;
    if (c >= C) return;

    float s = scale[c];
    // Welford online mean/var
    float m = 0.f, M2 = 0.f;
    int count = 0;

    // Each thread handles multiple rows
    for (int n = threadIdx.x; n < N; n += BLOCK) {
        float val = x[n * C + c] * s;
        count++;
        float delta = val - m;
        m += delta / count;
        float delta2 = val - m;
        M2 += delta * delta2;
    }

    // Warp reduce
    __shared__ float smem_m[BLOCK / 32];
    __shared__ float smem_M2[BLOCK / 32];
    __shared__ int   smem_n[BLOCK / 32];

    // Combine across warp lanes using Chan's parallel Welford
    unsigned mask = 0xffffffff;
    for (int offset = 16; offset >= 1; offset >>= 1) {
        float om    = __shfl_down_sync(mask, m, offset);
        float oM2   = __shfl_down_sync(mask, M2, offset);
        int   ocnt  = __shfl_down_sync(mask, count, offset);
        // merge
        int combined = count + ocnt;
        if (combined > 0) {
            float delta = om - m;
            m   = (m * count + om * ocnt) / combined;
            M2 += oM2 + delta * delta * (float)count * (float)ocnt / (float)combined;
        }
        count = combined;
    }

    int lane = threadIdx.x & 31;
    int warp = threadIdx.x >> 5;
    if (lane == 0) {
        smem_m[warp]  = m;
        smem_M2[warp] = M2;
        smem_n[warp]  = count;
    }
    __syncthreads();

    // Final reduction in warp 0
    int num_warps = BLOCK / 32;
    if (warp == 0) {
        m     = (lane < num_warps) ? smem_m[lane]  : 0.f;
        M2    = (lane < num_warps) ? smem_M2[lane] : 0.f;
        count = (lane < num_warps) ? smem_n[lane]  : 0;

        for (int offset = num_warps / 2; offset >= 1; offset >>= 1) {
            float om   = __shfl_down_sync(mask, m, offset);
            float oM2  = __shfl_down_sync(mask, M2, offset);
            int   ocnt = __shfl_down_sync(mask, count, offset);
            int combined = count + ocnt;
            if (combined > 0) {
                float delta = om - m;
                m   = (m * count + om * ocnt) / combined;
                M2 += oM2 + delta * delta * (float)count * (float)ocnt / (float)combined;
            }
            count = combined;
        }

        if (lane == 0) {
            mean_buf[c] = m;
            // biased variance for BN (divide by N, not N-1)
            var_buf[c]  = (count > 0) ? M2 / (float)count : 0.f;
        }
    }
