// Grid: (N * C / BLOCK2,), Block: (BLOCK2,)
__global__ void scale_bn_apply_kernel(
    const float* __restrict__ x,      // [N, C]
    float*       __restrict__ out,    // [N, C]
    const float* __restrict__ scale,  // [C]
    const float* __restrict__ mean,   // [C]
    const float* __restrict__ var,    // [C]
    const float* __restrict__ weight, // [C]
