    } else {
        int total = N * C;
        int blocks_apply = (total + 255) / 256;
        scale_bn_apply_eval_kernel<<<blocks_apply, 256>>>(
            x.data_ptr<float>(),
            out.data_ptr<float>(),
            scale.data_ptr<float>(),
            running_mean.data_ptr<float>(),
            running_var.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias.data_ptr<float>(),
            (float)eps,
            N, C
